fn frame(t: i32) {
    host::display::clear(0x08080c);
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, host::compose::spawn_lib("lib-rng"));
    }
    let h: i32 = host::display::state_get(1);
    let st: i32 = host::compose::status(h);
    if st == 0 {
        host::display::draw_string(8, 8, "LOADING LIB-RNG", 0xffff00, 1);
    }
    if st == 2 {
        host::display::draw_string(8, 8, "LIB-RNG FAILED", 0xff0000, 1);
    }
    if st == 1 {
        let gen: i32 = t / 90;
        let mut ok: i32 = 1;
        let mut i: i32 = 0;
        while i < 10 {
            let x: i32 = host::compose::call(h, "pick", gen * 100 + i * 2, 10, 470, 0);
            if host::compose::call_ok() != 0 { ok = 0; }
            let y: i32 = host::compose::call(h, "pick", gen * 100 + i * 2 + 1, 40, 470, 0);
            if host::compose::call_ok() != 0 { ok = 0; }
            if ok == 1 {
                host::display::fill_rect(x, y, 14, 14, 0xff40ff);
            }
            i = i + 1;
        }
        if ok == 1 {
            host::display::draw_string(8, 8, "CONFETTI BY LIB-RNG", 0x00ff66, 1);
        } else {
            host::display::draw_string(8, 8, "A CALL FAILED", 0xff0000, 1);
        }
    }
    host::display::present();
}
